 3	import java.util.Objects;
 4	
 5	public final class BubbleSort {
 6	    private BubbleSort() {
 7	        // Utility class.
 8	    }
 9	
10	    public static void sort(int[] values) {
11	        Objects.requireNonNull(values, "values");
12	
13	        if (hasFewerThanTwoValues(values)) {
14	            return;
15	        }
16	
17	        for (int lastUnsortedIndex = values.length - 1; lastUnsortedIndex > 0; lastUnsortedIndex--) {
18	            if (!bubbleLargestValueToEnd(values, lastUnsortedIndex)) {
19	                return;
20	            }
21	        }
22	    }
23	
24	    public static int[] sortedCopy(int[] values) {
25	        Objects.requireNonNull(values, "values");
26	
27	        int[] sortedValues = values.clone();
28	        sort(sortedValues);
29	        return sortedValues;
30	    }
31	
32	    private static boolean hasFewerThanTwoValues(int[] values) {
33	        return values.length < 2;
34	    }
35	
36	    private static boolean bubbleLargestValueToEnd(int[] values, int lastUnsortedIndex) {
37	        boolean swapped = false;
38	
39	        for (int currentIndex = 0; currentIndex < lastUnsortedIndex; currentIndex++) {
40	            if (values[currentIndex] > values[currentIndex + 1]) {
41	                swap(values, currentIndex, currentIndex + 1);
42	                swapped = true;
43	            }
44	        }
45	
46	        return swapped;
47	    }
48	
49	    private static void swap(int[] values, int leftIndex, int rightIndex) {
50	        int temporary = values[leftIndex];
51	        values[leftIndex] = values[rightIndex];
52	        values[rightIndex] = temporary;
53	    }
54	}

